//! The in-band `Frame::StreamParams` event (oxideav-core 0.1.43): when a
//! new active SPS changes the output shape (size / cropping, chroma
//! format, bit depth), `receive_frame` returns one event carrying the
//! new `output_params()` answer immediately before the first frame of
//! the new shape — after every old-shape picture still waiting in the
//! §C.4 reorder queue, whatever the worker budget.
//!
//! Fixtures (`tests/fixtures/output_params/`, regenerated by
//! `gen_events.sh`, which records ffprobe's per-frame shape sequence
//! in `expected_events.txt`) are black-box libx264 encodes with three
//! B-frames between anchors, concatenated as raw Annex B streams:
//!
//! * `splice_5_shapes.h264` — 64x48 4:2:0 8-bit → 80x46 (new size and
//!   cropping) → 80x46 10-bit → 80x46 4:2:2 8-bit → 64x48 4:2:0 8-bit,
//!   10 frames each;
//! * `splice_same_shape.h264` — two coded video sequences of one shape.

use oxideav_core::{
    CodecId, CodecParameters, Decoder, ExecutionContext, Frame, OutputParamsWatch, Packet,
    PixelFormat, TimeBase, VideoFrame,
};
use oxideav_h264::h264_decoder::H264CodecDecoder;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/output_params");

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("{DIR}/{name}")).expect("fixture")
}

/// ffprobe's per-frame shape sequence for `name`, run-length coded:
/// `(count, width, height, pix_fmt)`.
fn expected_runs(name: &str) -> Vec<(usize, u32, u32, PixelFormat)> {
    let text = std::fs::read_to_string(format!("{DIR}/expected_events.txt")).expect("expected");
    let line = text
        .lines()
        .find(|l| l.split_whitespace().next() == Some(name))
        .unwrap_or_else(|| panic!("{name} not in expected_events.txt"));
    line.split_whitespace()
        .skip(1)
        .map(|run| {
            let (n, shape) = run.split_once(':').expect("run");
            let f: Vec<&str> = shape.split(',').collect();
            let pf = match f[2] {
                "yuv420p" => PixelFormat::Yuv420P,
                "yuv422p" => PixelFormat::Yuv422P,
                "yuv420p10le" => PixelFormat::Yuv420P10Le,
                other => panic!("unexpected pix_fmt {other}"),
            };
            (
                n.parse().unwrap(),
                f[0].parse().unwrap(),
                f[1].parse().unwrap(),
                pf,
            )
        })
        .collect()
}

/// Split an Annex B byte stream into NAL unit payloads (no start code).
fn nal_payloads(data: &[u8]) -> Vec<&[u8]> {
    let mut starts = Vec::new();
    let mut i = 0usize;
    while i + 3 <= data.len() {
        if data[i] == 0 && data[i + 1] == 0 && data[i + 2] == 1 {
            starts.push(i + 3);
            i += 3;
        } else {
            i += 1;
        }
    }
    (0..starts.len())
        .map(|k| {
            let mut end = starts.get(k + 1).map(|&s| s - 3).unwrap_or(data.len());
            while end > starts[k] && data[end - 1] == 0 {
                end -= 1;
            }
            &data[starts[k]..end]
        })
        .collect()
}

fn annex_b(nals: &[&[u8]]) -> Vec<u8> {
    let mut out = Vec::new();
    for n in nals {
        out.extend_from_slice(&[0, 0, 0, 1]);
        out.extend_from_slice(n);
    }
    out
}

/// The stream cut into independently decodable pieces, one per SPS
/// (every libx264 IDR repeats its parameter sets).
fn pieces(bytes: &[u8]) -> Vec<Vec<u8>> {
    let nals = nal_payloads(bytes);
    let mut cuts: Vec<usize> = (0..nals.len())
        .filter(|&i| nals[i][0] & 0x1f == 7)
        .collect();
    assert_eq!(cuts.first(), Some(&0), "stream opens with an SPS");
    cuts.push(nals.len());
    cuts.windows(2)
        .map(|w| annex_b(&nals[w[0]..w[1]]))
        .collect()
}

/// The output-describing fields of a `CodecParameters`.
fn desc(p: &CodecParameters) -> (Option<u32>, Option<u32>, Option<PixelFormat>) {
    (p.width, p.height, p.pixel_format)
}

/// One `receive_frame` result.
#[derive(Clone, Debug, PartialEq)]
enum Out {
    /// A picture: pts, plane bytes, and the generation after it.
    Video(Option<i64>, Vec<Vec<u8>>, u64),
    /// An event: its shape and the generation when it was returned.
    Event(Option<u32>, Option<u32>, Option<PixelFormat>, u64),
}

/// Pull every available output, checking the contract on each:
/// an event equals the answer and comes with exactly one bump; a
/// picture never bumps and has the planes the answer describes.
fn drain(dec: &mut H264CodecDecoder, out: &mut Vec<Out>, gen_seen: &mut u64, tag: &str) {
    while let Ok(f) = dec.receive_frame() {
        let g = dec.output_params_generation();
        let answer = dec.output_params().expect("answer after output");
        match f {
            Frame::StreamParams(p) => {
                assert_eq!(desc(&p), desc(&answer), "{tag}: event == output_params()");
                assert_eq!(p.frame_rate, answer.frame_rate, "{tag}: event rate");
                assert_eq!(p.color_signal, answer.color_signal, "{tag}: event colour");
                assert_eq!(g, gen_seen.wrapping_add(1), "{tag}: one bump per event");
                *gen_seen = g;
                out.push(Out::Event(p.width, p.height, p.pixel_format, g));
            }
            Frame::Video(vf) => {
                assert_eq!(g, *gen_seen, "{tag}: a bump without its event");
                assert_geometry(&vf, &answer, tag);
                out.push(Out::Video(
                    vf.pts,
                    vf.planes.into_iter().map(|p| p.data).collect(),
                    g,
                ));
            }
            other => panic!("{tag}: unexpected frame {other:?}"),
        }
    }
}

fn assert_geometry(vf: &VideoFrame, p: &CodecParameters, tag: &str) {
    let (w, h) = (p.width.unwrap() as usize, p.height.unwrap() as usize);
    let (bps, sx, sy) = match p.pixel_format.unwrap() {
        PixelFormat::Yuv420P => (1, 2, 2),
        PixelFormat::Yuv422P => (1, 2, 1),
        PixelFormat::Yuv420P10Le => (2, 2, 2),
        other => panic!("{tag}: unexpected {other:?}"),
    };
    let got: Vec<(usize, usize)> = vf
        .planes
        .iter()
        .map(|pl| (pl.stride, pl.data.len() / pl.stride))
        .collect();
    let c = (w.div_ceil(sx) * bps, h.div_ceil(sy));
    assert_eq!(got, vec![(w * bps, h), c, c], "{tag}: planes vs answer");
}

fn decoder(threads: usize) -> H264CodecDecoder {
    let mut dec = H264CodecDecoder::new(CodecId::new("h264"));
    dec.set_execution_context(&ExecutionContext::with_threads(threads));
    dec
}

fn packet(data: Vec<u8>, pts: i64) -> Packet {
    Packet::new(0, TimeBase::new(1, 25), data).with_pts(pts)
}

/// Decode an Annex B stream one NAL per packet, draining after each.
fn decode_streamed(bytes: &[u8], threads: usize, tag: &str) -> Vec<Out> {
    let mut dec = decoder(threads);
    let (mut out, mut g) = (Vec::new(), 0);
    for (i, nal) in nal_payloads(bytes).into_iter().enumerate() {
        let _ = dec.send_packet(&packet(annex_b(&[nal]), i as i64));
        drain(&mut dec, &mut out, &mut g, tag);
    }
    dec.flush().expect("flush");
    drain(&mut dec, &mut out, &mut g, tag);
    out
}

/// Decode a whole stream as one packet, then flush and drain: every
/// SPS has been parsed before the first picture comes out.
fn decode_queued(bytes: &[u8], threads: usize, tag: &str) -> Vec<Out> {
    let mut dec = decoder(threads);
    let (mut out, mut g) = (Vec::new(), 0);
    dec.send_packet(&packet(bytes.to_vec(), 0)).expect("send");
    dec.flush().expect("flush");
    drain(&mut dec, &mut out, &mut g, tag);
    out
}

/// The pictures of an output sequence (events dropped).
fn pictures(out: &[Out]) -> Vec<Vec<Vec<u8>>> {
    out.iter()
        .filter_map(|o| match o {
            Out::Video(_, planes, _) => Some(planes.clone()),
            Out::Event(..) => None,
        })
        .collect()
}

/// `(index of the picture following the event, shape, generation)`.
type EventAt = (usize, (Option<u32>, Option<u32>, Option<PixelFormat>), u64);

fn events(out: &[Out]) -> Vec<EventAt> {
    let mut n = 0;
    let mut ev = Vec::new();
    for o in out {
        match o {
            Out::Video(..) => n += 1,
            Out::Event(w, h, pf, g) => ev.push((n, (*w, *h, *pf), *g)),
        }
    }
    ev
}

/// What ffprobe's shape runs predict: one event at every run boundary.
fn expected_events(name: &str) -> (usize, Vec<EventAt>) {
    let runs = expected_runs(name);
    let mut n = 0;
    let mut ev = Vec::new();
    for (k, &(count, w, h, pf)) in runs.iter().enumerate() {
        if k > 0 {
            ev.push((n, (Some(w), Some(h), Some(pf)), k as u64));
        }
        n += count;
    }
    (n, ev)
}

/// Each SPS piece decoded on its own: the reference pictures.
fn reference_pictures(bytes: &[u8]) -> Vec<Vec<Vec<u8>>> {
    let mut all = Vec::new();
    for piece in pieces(bytes) {
        let mut dec = decoder(1);
        dec.send_packet(&packet(piece, 0)).expect("send");
        dec.flush().expect("flush");
        let (mut out, mut g) = (Vec::new(), 0);
        drain(&mut dec, &mut out, &mut g, "piece");
        assert!(events(&out).is_empty(), "one shape per piece");
        all.extend(pictures(&out));
    }
    all
}

#[test]
fn one_event_per_change_before_its_first_frame_at_1_4_8_workers() {
    let name = "splice_5_shapes.h264";
    let bytes = fixture(name);
    let (frames, want) = expected_events(name);
    assert_eq!((frames, want.len()), (50, 4));
    let reference = reference_pictures(&bytes);
    assert_eq!(reference.len(), frames);
    let base = decode_streamed(&bytes, 1, "1 worker");
    for threads in [1, 4, 8] {
        for (mode, out) in [
            ("streamed", decode_streamed(&bytes, threads, "streamed")),
            ("queued", decode_queued(&bytes, threads, "queued")),
        ] {
            let tag = format!("{mode}, {threads} worker(s)");
            assert_eq!(events(&out), want, "{tag}: events vs ffprobe's shape runs");
            // Old-shape pictures drained first: every picture is
            // bit-identical to the one its own piece decodes to, in
            // the same order.
            assert!(pictures(&out) == reference, "{tag}: pictures vs pieces");
            if mode == "streamed" {
                assert!(out == base, "{tag}: identical to 1 worker");
            }
        }
    }
}

#[test]
fn no_event_on_a_constant_shape() {
    let bytes = fixture("splice_same_shape.h264");
    let (frames, want) = expected_events("splice_same_shape.h264");
    assert!(want.is_empty());
    for threads in [1, 4, 8] {
        for out in [
            decode_streamed(&bytes, threads, "same"),
            decode_queued(&bytes, threads, "same"),
        ] {
            assert_eq!(pictures(&out).len(), frames);
            assert!(events(&out).is_empty(), "{threads}: no event");
            assert!(out.iter().all(|o| matches!(o, Out::Video(_, _, 0))));
        }
    }
    // Nor for the first shape, which the answer states up front.
    let mut dec = decoder(1);
    dec.send_packet(&packet(bytes.clone(), 0)).expect("send");
    let before = dec.output_params().expect("announced from the SPS");
    assert_eq!(
        desc(&before),
        (Some(64), Some(48), Some(PixelFormat::Yuv420P))
    );
    dec.flush().expect("flush");
    assert!(matches!(dec.receive_frame(), Ok(Frame::Video(_))));
}

#[test]
fn the_8_to_10_bit_switch_and_the_watch_helpers_agree() {
    let bytes = fixture("splice_5_shapes.h264");
    for threads in [1, 8] {
        let mut dec = decoder(threads);
        dec.send_packet(&packet(bytes.clone(), 0)).expect("send");
        dec.flush().expect("flush");
        let (mut by_counter, mut by_event) = (
            CodecParameters::video(CodecId::new("h264")),
            CodecParameters::video(CodecId::new("h264")),
        );
        let (mut counter, mut event) = (OutputParamsWatch::new(), OutputParamsWatch::new());
        counter.prime(&dec, &mut by_counter);
        counter.prime(&dec, &mut by_event);
        let (mut n, mut seen_counter, mut seen_event) = (0, Vec::new(), Vec::new());
        while let Ok(f) = dec.receive_frame() {
            if counter.observe(&dec, &mut by_counter) {
                seen_counter.push(n);
            }
            if event.observe_frame(&f, &mut by_event) {
                seen_event.push(n);
            }
            if let Frame::Video(vf) = f {
                assert_geometry(&vf, &by_counter, "counter-tracked");
                assert_geometry(&vf, &by_event, "event-tracked");
                // The 8 → 10-bit switch at picture 20: two bytes per
                // sample from the first 10-bit picture on, not before.
                let wide = (20..30).contains(&n);
                assert_eq!(
                    vf.planes[0].stride,
                    if wide {
                        160
                    } else {
                        by_event.width.unwrap() as usize
                    }
                );
                n += 1;
            }
        }
        assert_eq!(n, 50);
        // The counter watch's first observe reads the stream once
        // (frame 0, no change since primed); both then see 4 changes.
        assert_eq!(seen_event, vec![10, 20, 30, 40], "{threads}: event watch");
        assert_eq!(
            seen_counter,
            vec![10, 20, 30, 40],
            "{threads}: counter watch"
        );
        assert_eq!(dec.output_params_generation(), 4);
    }
}

#[test]
fn reset_compares_with_the_last_shape_returned() {
    let bytes = fixture("splice_5_shapes.h264");
    let p = pieces(&bytes);
    // Pieces: 2 per segment (an IDR every 6 frames, 10 frames each).
    assert_eq!(p.len(), 10, "two IDRs per segment");
    for threads in [1, 4, 8] {
        let tag = format!("{threads} worker(s)");
        let mut dec = decoder(threads);
        let (mut out, mut g) = (Vec::new(), 0);
        // Segments 0 and 1 (64x48 then 80x46), then a seek into the
        // 10-bit segment 2: one event for the seek's shape change.
        for piece in &p[..4] {
            dec.send_packet(&packet(piece.clone(), 0)).expect("send");
            drain(&mut dec, &mut out, &mut g, &tag);
        }
        dec.flush().expect("flush");
        drain(&mut dec, &mut out, &mut g, &tag);
        assert!(matches!(out.last(), Some(Out::Video(_, _, 1))));
        dec.reset().expect("reset");
        let before_seek = events(&out).len();
        for piece in &p[4..6] {
            dec.send_packet(&packet(piece.clone(), 0)).expect("send");
            drain(&mut dec, &mut out, &mut g, &tag);
        }
        dec.flush().expect("flush");
        drain(&mut dec, &mut out, &mut g, &tag);
        let ev = events(&out);
        assert_eq!(before_seek, 1, "{tag}: 64x48 → 80x46 before the seek");
        assert_eq!(ev.len(), 2, "{tag}: one more event after the seek");
        assert_eq!(
            ev[1].1,
            (Some(80), Some(46), Some(PixelFormat::Yuv420P10Le)),
            "{tag}: the seek's new shape"
        );
        assert!(
            matches!(out.last(), Some(Out::Video(_, _, 2))),
            "{tag}: frames after"
        );
        // A seek to a piece of the shape last returned: no event.
        dec.reset().expect("reset");
        let n = out.len();
        dec.send_packet(&packet(p[5].clone(), 0)).expect("send");
        dec.flush().expect("flush");
        drain(&mut dec, &mut out, &mut g, &tag);
        assert!(out.len() > n);
        assert!(out[n..].iter().all(|o| matches!(o, Out::Video(_, _, 2))));
    }
}

#[test]
fn reset_right_after_an_event_keeps_counter_and_answer_in_step() {
    let bytes = fixture("splice_5_shapes.h264");
    let p = pieces(&bytes);
    let mut dec = decoder(1);
    let mut out = Vec::new();
    for piece in &p[..3] {
        dec.send_packet(&packet(piece.clone(), 0)).expect("send");
    }
    dec.flush().expect("flush");
    // Pull up to (and including) the 64x48 → 80x46 event.
    while !matches!(out.last(), Some(Out::Event(..))) {
        let f = dec.receive_frame().expect("output");
        let gen_now = dec.output_params_generation();
        match f {
            Frame::StreamParams(sp) => {
                out.push(Out::Event(sp.width, sp.height, sp.pixel_format, gen_now))
            }
            Frame::Video(vf) => out.push(Out::Video(vf.pts, Vec::new(), gen_now)),
            _ => unreachable!(),
        }
    }
    assert_eq!(dec.output_params().unwrap().width, Some(80));
    let mut g = 1;
    // Seek back into the first segment before the held 80x46 picture
    // is taken: the answer already moved to 80x46, so the 64x48 frames
    // after the seek are a change again — one more event, one bump
    // (the two events are adjacent: the picture between them was
    // discarded by the seek).
    dec.reset().expect("reset");
    dec.send_packet(&packet(p[0].clone(), 0)).expect("send");
    dec.flush().expect("flush");
    let n = out.len();
    drain(&mut dec, &mut out, &mut g, "after the seek");
    assert_eq!(
        out[n],
        Out::Event(Some(64), Some(48), Some(PixelFormat::Yuv420P), 2)
    );
    assert!(
        out[n + 1..]
            .iter()
            .all(|o| matches!(o, Out::Video(_, _, 2)))
    );
}

#[test]
fn receive_arena_frame_skips_the_event() {
    let bytes = fixture("splice_5_shapes.h264");
    let reference = reference_pictures(&bytes);
    for threads in [1, 8] {
        let mut dec = decoder(threads);
        dec.send_packet(&packet(bytes.clone(), 0)).expect("send");
        dec.flush().expect("flush");
        let mut n = 0;
        let mut gens = Vec::new();
        while let Ok(af) = dec.receive_arena_frame() {
            for (i, want) in reference[n].iter().enumerate() {
                assert_eq!(af.plane(i), Some(&want[..]), "picture {n} plane {i}");
            }
            gens.push(dec.output_params_generation());
            n += 1;
        }
        assert_eq!(n, 50, "{threads}: every picture, no event");
        let mut want = Vec::new();
        for g in 0..5u64 {
            want.extend(std::iter::repeat_n(g, 10));
        }
        assert_eq!(gens, want, "{threads}: the counter still moves");
    }
}
